const pad=(n:number)=>String(n).padStart(2,'0');
const dateStr=(d:Date)=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const parseDate=(s:string)=>{const p=s.split('-').map(Number);return new Date(p[0],p[1]-1,p[2],12,0,0)};
const addDays=(d:Date,n:number)=>{const r=new Date(d.getFullYear(),d.getMonth(),d.getDate(),12,0,0);r.setDate(r.getDate()+n);return r};
const prettyMonth=(d:Date)=>d.toLocaleDateString('en-US',{month:'long',year:'numeric'});
const prettyDate=(s:string)=>s?parseDate(s).toLocaleDateString('en-US',{month:'short',day:'numeric'}):'';
const weekday=(d:Date)=>d.toLocaleDateString('en-US',{weekday:'short'}).toUpperCase();
const mins=(s:string)=>{const [h,m]=(s||'00:00').split(':').map(Number);return h*60+m};
const timeFromMin=(n:number)=>`${pad(Math.floor(Math.max(0,Math.min(1439,n))/60))}:${pad(Math.max(0,Math.min(1439,n))%60)}`;
const prettyTime=(s:string)=>{const m=mins(s),h=Math.floor(m/60);return `${h%12||12}:${pad(m%60)} ${h<12?'AM':'PM'}`};
const uid=()=>`${Date.now().toString(36)}${Math.random().toString(36).slice(2,8)}`;
const escapeText=(s:string)=>s.replace(/[<>]/g,'').trim();
